import Ajv, {type ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
}

const schemaValidatorOptions = {strict: false, validateFormats: false};

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly schemaValidator = new Ajv(schemaValidatorOptions);
  private readonly validators = new WeakMap<Record<string, unknown>, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  private validatorFor(definition: ToolDefinition): ValidateFunction {
    const cached = this.validators.get(definition.inputSchema);
    if (cached) return cached;

    try {
      this.schemaValidator.validateSchema(definition.inputSchema, true);
      const validator = this.schemaValidator.compile(validationSchema(definition.inputSchema));
      this.validators.set(definition.inputSchema, validator);
      return validator;
    } catch (error) {
      const message = error instanceof Error ? error.message : 'unknown schema error';
      throw new Error(`Invalid inputSchema for tool ${definition.name}: ${message}`, {cause: error});
    }
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    if (typeof definition !== 'function') {
      this.validatorFor(resolved);
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Returns input-schema rejections; see specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const definition = this.resolveDefinition(tool.definitionSource);
    const validator = this.validatorFor(definition);
    if (!validator(input)) return {result: formatValidationErrors(validator.errors)};
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

interface ValidationError {
  keyword: string;
  instancePath?: string;
  dataPath?: string;
  schemaPath?: string;
  message?: string;
  params: object;
}

function validationSchema(schema: Record<string, unknown>): Record<string, unknown> {
  return Object.fromEntries(
    Object.entries(schema).flatMap(([keyword, value]) => {
      if (isNestedSchemaKeyword(keyword)) return nestedSchemaEntry(keyword, value);
      if (keyword === 'items') return [[keyword, projectSchema(value)]];
      if (['type', 'enum', 'required', '$ref', '$schema'].includes(keyword)) return [[keyword, value]];
      return [];
    })
  );
}

function isNestedSchemaKeyword(keyword: string): boolean {
  return ['properties', 'patternProperties', '$defs', 'definitions'].includes(keyword);
}

function nestedSchemaEntry(keyword: string, value: unknown): [string, unknown][] {
  const projected = isRecord(value)
    ? Object.fromEntries(Object.entries(value).map(([name, nested]) => [name, projectSchema(nested)]))
    : value;
  return [[keyword, projected]];
}

function projectSchema(value: unknown): unknown {
  return isRecord(value) ? validationSchema(value) : value;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function formatValidationErrors(errors: ValidationError[] | null | undefined): string {
  if (!errors?.length) return 'Tool input does not match the declared schema.';

  return errors.map(formatValidationError).join('; ');
}

function formatValidationError(error: ValidationError): string {
  if (error.keyword === 'required') {
    return `${joinInstancePath(requiredPropertyParentPath(error), validationParameter(error, 'missingProperty'))} is required.`;
  }
  if (error.keyword === 'type') {
    return `${errorPath(error)} must be a ${String(validationParameter(error, 'type'))}.`;
  }
  if (error.keyword === 'enum') {
    return `${errorPath(error)} must match an allowed value.`;
  }
  return `${error.instancePath || '/'} ${error.message ?? 'does not match the declared schema'}.`;
}

function errorPath(error: ValidationError): string {
  return normalizeInstancePath(error.instancePath || error.dataPath) || '/';
}

function validationParameter(error: ValidationError, parameter: string): unknown {
  return (error.params as Record<string, unknown>)[parameter];
}

function joinInstancePath(instancePath: string | undefined, property: unknown): string {
  return `${instancePath || ''}/${String(property)}`;
}

function requiredPropertyParentPath(error: ValidationError): string | undefined {
  return normalizeInstancePath(error.instancePath || error.dataPath) || parentPathFromSchemaPath(error.schemaPath);
}

function normalizeInstancePath(path: string | undefined): string | undefined {
  if (!path || path.startsWith('/')) return path;
  return path.replaceAll('.', '/');
}

function parentPathFromSchemaPath(schemaPath: string | undefined): string | undefined {
  if (!schemaPath) return undefined;

  const propertySegments = schemaPath
    .split('/')
    .slice(1, -1)
    .filter(segment => segment !== 'properties');
  return propertySegments.length ? `/${propertySegments.join('/')}` : undefined;
}
import {ToolRegistry} from './registry.js';

function registryWithWeatherSchema(inputSchema: Record<string, unknown>): ToolRegistry {
  const registry = new ToolRegistry();
  registry.register({name: 'weather', description: 'Gets weather', inputSchema}, async () => 'sunny');
  return registry;
}

function nestedLocationSchema(required: string[]): Record<string, unknown> {
  return {
    type: 'object',
    properties: {
      location: {
        type: 'object',
        properties: {
          postalCode: {type: 'string'},
          ...(required.includes('country') ? {country: {type: 'string'}} : {}),
        },
        required,
      },
    },
    required: ['location'],
  };
}

describe('ToolRegistry', () => {
  it('rejects an invalid ignored constraint at registration', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'weather',
          description: 'Gets weather',
          inputSchema: {type: 'object', minimum: 'one'},
        },
        async () => 'sunny'
      )
    ).toThrow('weather');
  });

  it('passes valid input with undeclared properties through unchanged exactly once', async () => {
    const registry = new ToolRegistry();
    const input = {location: 'Paris', language: 'fr'};
    const receivedInputs: Array<Record<string, unknown>> = [];
    registry.register(
      {
        name: 'weather',
        description: 'Gets weather',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async executorInput => {
        receivedInputs.push(executorInput);
        return 'sunny';
      }
    );

    const response = await registry.execute('weather', input);

    expect({response, receivedInputs}).toEqual({
      response: {result: 'sunny'},
      receivedInputs: [input],
    });
  });

  it('passes a type-valid value that is below an unvalidated numeric bound to the executor', async () => {
    const registry = new ToolRegistry();
    const receivedInputs: Array<Record<string, unknown>> = [];
    registry.register(
      {
        name: 'weather',
        description: 'Gets weather',
        inputSchema: {
          type: 'object',
          properties: {days: {type: 'number', minimum: 1}},
          required: ['days'],
        },
      },
      async input => {
        receivedInputs.push(input);
        return 'sunny';
      }
    );

    const response = await registry.execute('weather', {days: 0});

    expect({response, receivedInputs}).toEqual({response: {result: 'sunny'}, receivedInputs: [{days: 0}]});
  });

  it('uses the current schema from a function-valued definition source', async () => {
    const registry = new ToolRegistry();
    let useLocationSchema = false;
    const executorCalls: Array<Record<string, unknown>> = [];

    registry.register(
      () => ({
        name: 'weather',
        description: 'Gets weather',
        inputSchema: useLocationSchema
          ? {type: 'object', properties: {location: {type: 'string'}}, required: ['location']}
          : {type: 'object', properties: {city: {type: 'string'}}, required: ['city']},
      }),
      async input => {
        executorCalls.push(input);
        return 'sunny';
      }
    );

    const cityResponse = await registry.execute('weather', {city: 'Paris'});
    useLocationSchema = true;
    const staleInputResponse = await registry.execute('weather', {city: 'Paris'});
    const locationResponse = await registry.execute('weather', {location: 'Paris'});

    expect({cityResponse, staleInputResponse, locationResponse, executorCalls}).toEqual({
      cityResponse: {result: 'sunny'},
      staleInputResponse: {result: expect.stringContaining('location')},
      locationResponse: {result: 'sunny'},
      executorCalls: [{city: 'Paris'}, {location: 'Paris'}],
    });
  });

  it('rejects a wrong-typed input without revealing its value', async () => {
    const registry = new ToolRegistry();
    const field = 'ssn';
    const rejectedValue = 123456789;
    let executorCalls = 0;
    registry.register(
      {
        name: 'identifier_lookup',
        description: 'Looks up an identifier',
        inputSchema: {
          type: 'object',
          properties: {[field]: {type: 'string'}},
          required: [field],
        },
      },
      async () => {
        executorCalls += 1;
        return 'found';
      }
    );

    const response = await registry.execute('identifier_lookup', {[field]: rejectedValue});

    expect({
      executorCalls,
      namesExpectedType: new RegExp(`${field}.*string`, 'i').test(response.result),
      leaksValue: response.result.includes(String(rejectedValue)),
    }).toEqual({
      executorCalls: 0,
      namesExpectedType: true,
      leaksValue: false,
    });
  });

  it('names the complete path for a nested missing required property', async () => {
    const registry = registryWithWeatherSchema(nestedLocationSchema(['postalCode']));

    const response = await registry.execute('weather', {location: {}});

    expect(response).toEqual({result: expect.stringMatching(/\/location\/postalCode.*required/i)});
  });

  it('formats legacy nested required paths as JSON Pointers', async () => {
    const registry = registryWithWeatherSchema(nestedLocationSchema(['postalCode', 'country']));

    const response = await registry.execute('weather', {location: {}});

    expect(response).toEqual({result: expect.stringMatching(/^\/location\/postalCode is required\./)});
  });

  it('formats legacy enum paths as JSON Pointers', async () => {
    const registry = new ToolRegistry();
    const validator = Object.assign(() => false, {
      errors: [
        {
          keyword: 'enum',
          dataPath: '.status',
          params: {allowedValues: ['open', 'closed']},
        },
      ],
    });
    (registry as unknown as {schemaValidator: {compile: () => typeof validator}}).schemaValidator.compile = () =>
      validator;
    registry.register(
      () => ({name: 'ticket', description: 'Gets a ticket', inputSchema: {type: 'object'}}),
      async () => 'open'
    );

    const response = await registry.execute('ticket', {status: 'other'});

    expect(response).toEqual({result: '/status must match an allowed value.'});
  });

  it('normalizes a legacy dotted dataPath in a required-property rejection', async () => {
    const registry = new ToolRegistry();
    const validator = Object.assign(() => false, {
      errors: [
        {
          keyword: 'required',
          dataPath: '.location',
          params: {missingProperty: 'postalCode'},
        },
      ],
    });
    (registry as unknown as {schemaValidator: {compile: () => typeof validator}}).schemaValidator.compile = () =>
      validator;
    registry.register(
      () => ({name: 'weather', description: 'Gets weather', inputSchema: {type: 'object'}}),
      async () => 'sunny'
    );

    const response = await registry.execute('weather', {location: {}});

    expect(response).toEqual({result: '/location/postalCode is required.'});
  });

  it('compiles a static schema once across repeated executions', async () => {
    const registry = new ToolRegistry();
    let compileCalls = 0;
    let executorCalls = 0;
    const validator = Object.assign(() => true, {errors: null});
    (registry as unknown as {schemaValidator: {compile: () => typeof validator}}).schemaValidator.compile = () => {
      compileCalls += 1;
      return validator;
    };
    registry.register({name: 'weather', description: 'Gets weather', inputSchema: {type: 'object'}}, async () => {
      executorCalls += 1;
      return 'sunny';
    });

    await Promise.all(Array.from({length: 10}, () => registry.execute('weather', {})));

    expect({compileCalls, executorCalls}).toEqual({compileCalls: 1, executorCalls: 10});
  });
});
